#[tokio::test]
async fn absent_config_is_fail_open_absent() {
    let svc = service(Ok(None), Box::new(FailingRunner));
    assert_eq!(
        svc.evaluate(uuid::Uuid::nil(), &step("payment_execute", json!({})))
            .await
            .expect("evaluate"),
        PreconditionVerdict::Dispatch
    );
    assert!(!svc.is_configured().await.expect("configured"));
}

#[tokio::test]
async fn corrupt_config_fails_closed() {
    let svc = service(
        Err(PreconditionError::ConfigInvalid("bad".to_string())),
        Box::new(FailingRunner),
    );
    let error = svc
        .evaluate(uuid::Uuid::nil(), &step("payment_execute", json!({})))
        .await
        .expect_err("fail closed");
    assert!(!error.is_retriable());
}

#[tokio::test]
async fn determinism_same_input_same_verdict() {
    // AC #9: identical step + config + deterministic check → identical verdict.
    let svc = service(
        Ok(Some(config(vec![precondition(
            "p1",
            "payment_execute",
            &[],
        )]))),
        Box::new(RecordingRunner {
            calls: Arc::new(Mutex::new(Vec::new())),
            outcome: PreconditionOutcome::Passed,
        }),
    );
    let step = step("payment_execute", json!({ "beneficiary": "acct-1" }));
    let first = svc
        .evaluate(uuid::Uuid::nil(), &step)
        .await
        .expect("evaluate");
    for _ in 0..50 {
        assert_eq!(
            svc.evaluate(uuid::Uuid::nil(), &step)
                .await
                .expect("evaluate"),
            first
        );
    }
}

#[tokio::test]
async fn is_configured_reports_precondition_presence() {
    let configured = service(
        Ok(Some(config(vec![precondition(
            "p1",
            "payment_execute",
            &[],
        )]))),
        Box::new(FailingRunner),
    );
    assert!(configured.is_configured().await.expect("configured"));
    let empty = service(Ok(Some(config(vec![]))), Box::new(FailingRunner));
    assert!(!empty.is_configured().await.expect("configured"));
}
